/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

explore.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

category.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

search.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

detail.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

chapters.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

episodes.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
      var tag = im[0];
      var ds = _ehAttr(tag, 'data-src');
      if (ds) cands.push(ds);
      var sc = _ehAttr(tag, 'src');
      if (sc) cands.push(sc);
      var st = _ehAttr(tag, 'style');
      if (st) cands.push(_ehStyleUrl(st));
    }
    var stRe = /style="[^"]*url\([^"]*\)"/gi;
    var sm;
    while ((sm = stRe.exec(row)) !== null) cands.push(_ehStyleUrl(sm[0]));
    for (var ci = 0; ci < cands.length && !cover; ci++) {
      cover = _ehUsableCover(cands[ci]);
    }
    cover = _ehAbs(cover, base);
    // 分类 / 上传者 / 页数（站点在 .cn/.cs、.glhide/.gl4c 里）
    var category = _ehText(_ehByClass(row, 'cn')) || _ehText(_ehByClass(row, 'cs'));
    var uploader = '';
    var upM = /<a\s[^>]*href=["'][^"']*\/uploader\/[^"']*["'][^>]*>([\s\S]*?)<\/a>/i.exec(row);
    if (upM) uploader = _ehText(upM[1]);
    var pages = 0;
    var pgM = /<div>(\d+)\s*pages<\/div>/i.exec(row);
    if (pgM) pages = parseInt(pgM[1], 10) || 0;
    var posted = _ehText(_ehById(row, 'posted_' + g.gid));
    if (!posted) {
      var pdM = /(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2})/.exec(row);
      if (pdM) posted = pdM[1];
    }
    // 标签：.gt/.gtl 的 title 属性（形如 "parody:xxx"）
    var tags = [];
    var tRe = /<div[^>]*class="[^"]*\bgtl?\b[^"]*"[^>]*>/gi;
    var tm;
    while ((tm = tRe.exec(row)) !== null) {
      var t = _ehAttr(tm[0], 'title');
      if (t) tags.push(t);
    }
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: _ehAbs(href, base),
      author: uploader,
      tags: tags,
      status: pages ? pages + ' 页' : '',
      updatedAt: posted ? posted.replace(' ', 'T') : '',
      extra: { gid: g.gid, token: g.token, category: category, pages: pages },
    });
  }
  try { if (ctx.log) ctx.log('parseList: rows=' + rows.length + ', items=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   详情
   =========================================================================== */

function parseDetail(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return null;

  // 标题：#gn（英文）→ #gj（日文）回退
  var title = _ehText(_ehById(h, 'gn')) || _ehText(_ehById(h, 'gj'));
  if (!title) return null;

  // 封面：#gd1 的第一个子元素的 style:url()
  var cover = '';
  var gd1 = _ehById(h, 'gd1');
  if (gd1) {
    var m = /<div\b([^>]*)>/i.exec(gd1);
    if (m) cover = _ehStyleUrl(m[1]);
    if (!cover) {
      var im = /<img\b[^>]*>/i.exec(gd1);
      if (im) cover = _ehAttr(im[0], 'src');
    }
  }
  cover = _ehAbs(_ehUsableCover(cover), base);

  // 分类 / 上传者
  var category = _ehText(_ehById(h, 'gdc'));
  var uploader = '';
  var gdn = _ehById(h, 'gdn');
  if (gdn) {
    var um = /<a\b[^>]*>([\s\S]*?)<\/a>/i.exec(gdn);
    uploader = _ehText(um ? um[1] : gdn);
  }

  // 元信息表：#gdd 的每行「键 → 值」
  var meta = {};
  var gdd = _ehById(h, 'gdd');
  if (gdd) {
    var rowRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var rm;
    while ((rm = rowRe.exec(gdd)) !== null) {
      var cellRe = /<td\b[^>]*>([\s\S]*?)<\/td>/gi;
      var c1 = cellRe.exec(rm[1]);
      var c2 = cellRe.exec(rm[1]);
      if (!c1 || !c2) continue;
      var key = _ehText(c1[1]).replace(/:$/, '').toLowerCase();
      var val = _ehText(c2[1]);
      if (key) meta[key] = val;
    }
  }
  var pages = 0;
  if (meta['length']) {
    var pm = /(\d+)/.exec(meta['length']);
    if (pm) pages = parseInt(pm[1], 10) || 0;
  }

  // 标签：#taglist 每行「命名空间 → 标签」
  var tags = [];
  var tagUrls = [];
  var tl = _ehById(h, 'taglist');
  if (tl) {
    var trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    var trm;
    while ((trm = trRe.exec(tl)) !== null) {
      var rowHtml = trm[1];
      var nsM = /<td\b[^>]*class="[^"]*\btc\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i.exec(rowHtml);
      if (!nsM) continue;
      var ns = _ehText(nsM[1]).replace(/:$/, '');
      var valCell = rowHtml.substring(nsM.index + nsM[0].length);
      var aRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
      var am;
      while ((am = aRe.exec(valCell)) !== null) {
        var t = _ehText(am[2]);
        if (!t) continue;
        tags.push(ns ? ns + ':' + t : t);
        var href = _ehAttr('<a ' + am[1] + '>', 'href');
        tagUrls.push(_ehAbs(href, base));
      }
    }
  }

  var ratingCount = 0;
  var rc = _ehById(h, 'rating_count');
  if (rc) ratingCount = parseInt(_ehText(rc), 10) || 0;
  var ratingAvg = '';
  var rl = _ehById(h, 'rating_label');
  if (rl) {
    var am2 = /([0-9]+(?:\.[0-9]+)?)/.exec(_ehText(rl));
    if (am2) ratingAvg = am2[1];
  }

  var cano = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/i.exec(h);
  var detailUrl = cano ? cano[1] : (ctx.url || '');
  var g = _ehSplitGallery(detailUrl) || _ehSplitGallery(String(ctx.id || ''));
  var id = g ? 'g/' + g.gid + '/' + g.token + '/' : String(ctx.id || '');

  var descParts = [];
  if (category) descParts.push('分类: ' + category);
  if (pages) descParts.push(pages + ' 页');
  if (ratingAvg) descParts.push('评分: ' + ratingAvg + (ratingCount ? ' (' + ratingCount + '人)' : ''));
  if (meta['language']) descParts.push('语言: ' + meta['language']);
  if (meta['file size']) descParts.push('大小: ' + meta['file size']);

  return {
    id: id,
    title: title,
    cover: cover,
    detailUrl: detailUrl,
    description: descParts.join(' · '),
    author: uploader,
    authorUrl: uploader
      ? base + '/uploader/' + encodeURIComponent(uploader)
      : '',
    status: meta['posted'] || '',
    tags: tags,
    tagUrls: tagUrls,
    updatedAt: meta['posted'] ? meta['posted'].replace(' ', 'T') : '',
    extra: {
      gid: g ? g.gid : '',
      token: g ? g.token : '',
      category: category,
      pages: pages,
      ratingAvg: ratingAvg,
      ratingCount: ratingCount,
      favorited: meta['favorited'] || '',
      language: meta['language'] || '',
      fileSize: meta['file size'] || '',
    },
  };
}

/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
  var text = _ehText(gpc);
  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
  };
}

function parseChapters(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var id = String(ctx.id || '');
  var g = _ehSplitGallery(h) || _ehSplitGallery(id);
  if (!g) return [];
  var gid = 'g/' + g.gid + '/' + g.token + '/';
  var range = _ehRangeInfo(h);
  var total = range ? range.total : 0;
  if (!total) {
    // 兜底：数本页的 /s/ 链接
    var cnt = 0;
    var sRe = /href="[^"]*\/s\/[0-9a-f]+\/\d+-\d+[^"]*"/gi;
    while (sRe.exec(h) !== null) cnt++;
    total = cnt;
  }
  if (!total) return [];
  var size = _EH_PAGE_SIZE;
  var out = [];
  for (var start = 0; start < total; start += size) {
    var end = Math.min(total, start + size);
    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
    });
  }
  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var urls = [];
  var seen = {};
  var re = /<a\b[^>]*href=["']([^"']*\/s\/[0-9a-f]+\/\d+-\d+)["']/gi;
  var m;
  while ((m = re.exec(h)) !== null) {
    var u = _ehAbs(m[1], base);
    if (!seen[u]) { seen[u] = 1; urls.push(u); }
  }
  if (!urls.length) return [];
  return {
    __meta: true,
    __fetchUrls: urls,
    __fetchResponseType: 'text',
    __fetchConcurrency: 6,
    __processor: 'processImages',
  };
}

/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
    // 原图：<img ... src="..." style（与桌面端解析口径一致）
    var m = /<img[^>]*src="([^"]+)"[^>]*style/i.exec(html) ||
      /<img[^>]*\bid="img"[^>]*src="([^"]+)"/i.exec(html);
    if (m && m[1]) out.push(m[1]);
  }
  try {
    var ctx = context || {};
    if (ctx.log) ctx.log('processImages: ' + out.length + '/' + pages.length);
  } catch (e) {}
  return out;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    parseList: parseList,
    parseDetail: parseDetail,
    parseChapters: parseChapters,
    parseImages: parseImages,
    processImages: processImages,
  };
}

images.script:
/* ===========================================================================
   共享工具
   =========================================================================== */

/** 去标签 + 折叠空白。 */
function _ehText(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** 取某 id 元素的完整内容（支持一层同 id 嵌套，避免被首个闭标签截断）。 */
function _ehById(html, id) {
  var open = new RegExp('id="' + id + '"', 'i');
  var m = open.exec(html);
  if (!m) return '';
  // 标签起始：id 属性所在元素的 `<`
  var lt = html.lastIndexOf('<', m.index);
  if (lt < 0) return '';
  var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
  // 校验标签真的闭合（_ehTagEnd 未越界）
  if (_ehTagEnd(html, lt) <= lt) return '';
  // start 指向 `<` 本身
  return _ehSliceTag(html, lt, tagName ? tagName[1].toLowerCase() : '');
}

/**
 * 从开标签起始处（`<`）找到它的 `>`，返回「内容起点」下标。
 * 引号感知：跳过属性值内部的 `>`（如 onclick="return a>b"）。
 */
function _ehTagEnd(html, start) {
  var quote = '';
  for (var i = start; i < html.length; i++) {
    var ch = html[i];
    if (quote) {
      if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; continue; }
    if (ch === '>') return i + 1;
  }
  return start;
}

/**
 * 从 `start` 处开始做配对切片：返回与起始位置同名的标签所包裹的完整内容。
 * 站点大量使用嵌套 <div>，单纯的非贪婪正则会被内层闭标签截断，
 * 这里按标签名计数配对（只处理 div/td/tr/table 这类容器）。
 */
function _ehSliceTag(html, start, hint) {
  var names = [
    'div', 'td', 'tr', 'table', 'a', 'span', 'p', 'ul', 'li',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'section', 'article',
  ];
  var lower = html.toLowerCase();
  var name = '';
  if (hint && names.indexOf(hint) >= 0) {
    name = hint;
  } else {
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      if (lower.substr(start, n.length) !== n) continue;
      var after = lower.substr(start + n.length, 1);
      if (after === ' ' || after === '>') { name = n; break; }
    }
  }
  if (!name) return '';
  // 起始标签的 `>`（引号感知，属性值里可能含 `>`）。
  var cursor0 = _ehTagEnd(html, start);
  // 流式扫描：单正则同时匹配开/闭标签，从内容起点向后推。
  // 每消费一个标签 regex 的 lastIndex 自动推进，天然不重复消费；
  // 不使用占位符/控制字符（NUL 等可能在某些桥接/传输路径被截断），
  // 也不依赖两个正则分别找开/闭再比较（曾因互相干扰导致配对失败）。
  var depth = 1;
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)(?=[\s>\/])/g;
  re.lastIndex = cursor0;
  var guard = 0;
  var m;
  while ((m = re.exec(html)) !== null && guard++ < 200000) {
    if (m[1] === '/') {
      if (m[2].toLowerCase() === name) {
        depth--;
        if (depth === 0) return html.substring(cursor0, m.index);
      }
    } else if (m[2].toLowerCase() === name) {
      depth++;
    }
  }
  return '';
}

/** 取属性（大小写不敏感，支持单/双引号与无引号）。 */
function _ehAttr(tag, name) {
  var re = new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  var m = re.exec(tag || '');
  if (!m) return '';
  return m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] || ''));
}

/**
 * 取「class 属性含指定词」的第一个元素内容。
 * 必须按整词匹配且允许 class 多值（如 `class="itg gltc"`），
 * 否则 `itg` 会命中 `itgc` 之类、或干脆匹配不到多值写法。
 * 元素可能嵌套同名标签，故走配对切片。
 */
function _ehByClass(html, cls) {
  var re = new RegExp('class="[^"]*\\b' + cls + '\\b[^"]*"', 'gi');
  var m;
  while ((m = re.exec(html)) !== null) {
    var lt = html.lastIndexOf('<', m.index);
    if (lt < 0) continue;
    var tagName = /^<([a-zA-Z0-9]+)/.exec(html.substr(lt, 16));
    if (!tagName) continue;
    if (html.indexOf('>', m.index) < 0) continue;
    // start 指向 `<` 本身（_ehSliceTag 的约定）
    var body = _ehSliceTag(html, lt, tagName[1].toLowerCase());
    if (body) return body;
  }
  return '';
}

/** 取某元素起点的标签名（供外层判断）。 */
function _ehTagNameAt(html, pos) {
  var m = /^([a-zA-Z0-9]+)/.exec(html.substr(pos, 16));
  return m ? m[1].toLowerCase() : '';
}

/** 从 style 中取 url(...)。 */
function _ehStyleUrl(style) {
  var m = /url\((['"]?)(.*?)\1\)/i.exec(String(style || ''));
  return m ? String(m[2]).trim() : '';
}

/** 封面候选是否可用（排除占位图）。 */
var _EH_PLACEHOLDER = ['data:image', 'base64,', 'blank.gif', 'spacer', '/img/blank'];
function _ehUsableCover(url) {
  var v = String(url || '').trim().replace(/^['"]|['"]$/g, '');
  if (!v) return '';
  var low = v.toLowerCase();
  for (var i = 0; i < _EH_PLACEHOLDER.length; i++) {
    if (low.indexOf(_EH_PLACEHOLDER[i]) >= 0) return '';
  }
  if (v.indexOf('//') === 0) return 'https:' + v;
  return v;
}

/** 站点缩略图/原图地址规范化（补全协议与主机名）。 */
function _ehAbs(url, base) {
  var v = String(url || '').trim();
  if (!v) return '';
  if (v.indexOf('//') === 0) return 'https:' + v;
  if (v.indexOf('/') === 0) return base + v;
  return v;
}

/** 画廊 URL → { gid, token }。 */
function _ehSplitGallery(url) {
  var m = /(?:e-hentai\.org|exhentai\.org)\/(?:g|mpv)\/(\d+)\/([0-9a-f]{10})/i.exec(String(url || ''));
  if (!m) return null;
  return { gid: m[1], token: m[2] };
}

/* ===========================================================================
   列表 / 搜索 / 分类
   =========================================================================== */

/** 把列表容器切成「每个画廊一块」，兼容表格行与 div 两种布局。 */
function _ehSplitRows(html) {
  var container = _ehByClass(html, 'itg');
  var scope = container || html;
  var trRe = /<tr(?:\s[^>]*)?>/gi;
  if (trRe.test(scope)) {
    var rows = [];
    var re = /<tr(?:\s[^>]*)?>([\s\S]*?)<\/tr>/gi;
    var m;
    while ((m = re.exec(scope)) !== null) rows.push(m[1]);
    if (rows.length) return rows;
  }
  // div 布局：按顶层 <div 切分（跳过嵌套）
  var out = [];
  var lower = scope.toLowerCase();
  var depth = 0;
  var start = -1;
  var dre = /<div(\s|>)|<\/div>/gi;
  var dm;
  while ((dm = dre.exec(scope)) !== null) {
    var isOpen = lower[dm.index + 1] !== '/';
    if (isOpen) {
      if (depth === 0) start = dm.index;
      depth++;
    } else {
      if (depth > 0) depth--;
      if (depth === 0 && start >= 0) {
        out.push(scope.substring(start, dm.index + 6));
        start = -1;
      }
    }
  }
  return out;
}

function parseList(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
  if (!h || h.length < 50) return [];
  var out = [];
  var seen = {};
  var rows = _ehSplitRows(h);
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    // 标题：.glink（站点两种布局都用它承载标题）
    var title = _ehText(_ehByClass(row, 'glink'));
    if (!title) continue;
    // 详情链接：/g/<gid>/<token>/
    var href = '';
    var aRe = /<a\s[^>]*href=(["'])([^"']*\/g\/\d+\/[0-9a-f]{10}\/?[^"']*)\1/gi;
    var am = aRe.exec(row);
    if (am) href = am[2];
    if (!href) continue;
    var g = _ehSplitGallery(href);
    if (!g) continue;
    var id = 'g/' + g.gid + '/' + g.token + '/';
    if (seen[id]) continue;
    // 封面：优先 [data-src]，回退 [src]，再回退内联 style 的 url()
    var cover = '';
    var imgRe = /<img\b[^>]*>/gi;
    var im;
    var cands = [];
    while ((im = imgRe.exec(row)) !== null) {
