/* ===========================================================================
   章节：按缩略图分页切段（默认每段 20 页）
   =========================================================================== */

var _EH_PAGE_SIZE = 20;

function _ehRangeInfo(html) {
  var gpc = _ehByClass(html, 'gpc');
