  var m = /Showing\s+(\d+)\s*-\s*(\d+)\s+of\s+([\d,]+)\s+images/i.exec(text);
  if (!m) return null;
  return {
    from: parseInt(m[1], 10) || 1,
    to: parseInt(m[2], 10) || 1,
    total: parseInt(String(m[3]).replace(/,/g, ''), 10) || 0,
