    var page = Math.floor(start / size);
    out.push({
      id: gid + '@' + page,
      title: '第 ' + (start + 1) + '-' + end + ' 页',
      url: base + '/' + gid + (page > 0 ? '?p=' + page : ''),
      number: page + 1,
