  try { if (ctx.log) ctx.log('parseChapters: total=' + total + ', chapters=' + out.length); } catch (e) {}
  return out;
}

/* ===========================================================================
   图片：两段式（meta 批量预取 → 同步处理）
   =========================================================================== */

/** Step 1：从画廊页提取本段的 /s/ 链接，交给引擎批量预取。 */
function parseImages(html, context) {
  var ctx = context || {};
  var base = String(ctx.baseUrl || 'https://e-hentai.org').replace(/\/$/, '');
  var h = typeof html === 'string' ? html : '';
