/** Step 2：引擎批量预取完成后，同步从每个页面取原图地址。 */
function processImages(pages, context) {
  var out = [];
  if (!pages || pages.length === undefined) return out;
  for (var i = 0; i < pages.length; i++) {
    var html = pages[i];
    if (!html || typeof html !== 'string') continue;
